B.Tx=new A.fT("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.a_w=new A.C(45,40)
B.b4=new A.tE("marek","assets/images/stories/forest_rangers/portrait_marek.svg",B.a_w)
B.O8=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.a0o=new A.bw(B.b4,B.O8)
B.a_x=new A.C(46,40)
B.aA=new A.tE("karel","assets/images/stories/forest_rangers/portrait_karel.svg",B.a_x)
B.P8=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.a0b=new A.bw(B.aA,B.P8)
B.QV=s([B.Tx,B.a0o,B.a0b],t.GD)
B.a14=new A.fW("story_00_intro",B.QV)
B.Tr=new A.fT("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.On=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.a09=new A.bw(B.b4,B.On)
B.Tz=new A.fT("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.Ou=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.a0v=new A.bw(B.aA,B.Ou)
B.a_B=new A.C(56,59)
B.bb=new A.tE("tereza","assets/images/stories/forest_rangers/portrait_tereza.svg",B.a_B)
B.Qx=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.a0m=new A.bw(B.bb,B.Qx)
B.Ox=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.a05=new A.bw(B.b4,B.Ox)
B.Ot=s([B.Tr,B.a09,B.Tz,B.a0v,B.a0m,B.a05],t.GD)
B.a19=new A.fW("story_01a_clubhouse_arrival",B.Ot)
B.OL=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.a0w=new A.bw(B.b4,B.OL)
B.Pb=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.a0g=new A.bw(B.bb,B.Pb)
B.ND=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.a02=new A.bw(B.aA,B.ND)
B.Os=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.a04=new A.bw(B.bb,B.Os)
B.O9=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.a0z=new A.bw(B.aA,B.O9)
B.N8=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.a0t=new A.bw(B.b4,B.N8)
B.PN=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.a_X=new A.bw(B.aA,B.PN)
B.PM=s([B.a0w,B.a0g,B.a02,B.a04,B.a0z,B.a0t,B.a_X],t.GD)
B.a17=new A.fW("story_01b_legend_and_time",B.PM)
B.TB=new A.fT("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.ON=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.a06=new A.bw(B.aA,B.ON)
B.OE=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.a0d=new A.bw(B.bb,B.OE)
B.QJ=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.a0e=new A.bw(B.aA,B.QJ)
B.PF=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.a_Y=new A.bw(B.bb,B.PF)
B.O1=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.a01=new A.bw(B.b4,B.O1)
B.OP=s([B.TB,B.a06,B.a0d,B.a0e,B.a_Y,B.a01],t.GD)
B.a11=new A.fW("story_02_torn_map",B.OP)
B.NE=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.a_W=new A.bw(B.b4,B.NE)
B.Q6=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.a0A=new A.bw(B.aA,B.Q6)
B.Tu=new A.fT("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.Qy=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.a0C=new A.bw(B.bb,B.Qy)
B.QF=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.a_Z=new A.bw(B.aA,B.QF)
B.Px=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.a_T=new A.bw(B.b4,B.Px)
B.NS=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.a0a=new A.bw(B.aA,B.NS)
B.OJ=s([B.a_W,B.a0A,B.Tu,B.a0C,B.a_Z,B.a_T,B.a0a],t.GD)
B.a16=new A.fW("story_03_founders_trail",B.OJ)
B.Ts=new A.fT("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.OA=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.a_V=new A.bw(B.aA,B.OA)
B.PL=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.a0r=new A.bw(B.bb,B.PL)
B.Qu=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.a0q=new A.bw(B.aA,B.Qu)
B.OQ=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.a_S=new A.bw(B.b4,B.OQ)
B.Qw=s([B.Ts,B.a_V,B.a0r,B.a0q,B.a_S],t.GD)
B.a1a=new A.fW("story_04_flowers_in_mud",B.Qw)
B.Tw=new A.fT("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.Og=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.a0i=new A.bw(B.aA,B.Og)
B.Na=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.a03=new A.bw(B.bb,B.Na)
B.P1=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.a07=new A.bw(B.aA,B.P1)
B.QU=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.a0n=new A.bw(B.b4,B.QU)
B.PB=s([B.Tw,B.a0i,B.a03,B.a07,B.a0n],t.GD)
B.a13=new A.fW("story_05_old_oak",B.PB)
B.Tv=new A.fT("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.Q7=s(["\u201eCo se to stalo?\u201c"],t.s)
B.a0B=new A.bw(B.aA,B.Q7)
B.P0=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.a0_=new A.bw(B.b4,B.P0)
B.Ok=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.a0y=new A.bw(B.aA,B.Ok)
B.Pa=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.a_U=new A.bw(B.b4,B.Pa)
B.Tt=new A.fT("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.P3=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.a0h=new A.bw(B.bb,B.P3)
B.Qj=s([B.Tv,B.a0B,B.a0_,B.a0y,B.a_U,B.Tt,B.a0h],t.GD)
B.a12=new A.fW("story_06_waterfall_chest",B.Qj)
B.Ty=new A.fT("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.OF=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.a0k=new A.bw(B.bb,B.OF)
B.QN=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.a0u=new A.bw(B.b4,B.QN)
B.TA=new A.fT("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
